const uint16_t g_cjk_count = (uint16_t)(sizeof(g_cjk) / sizeof(g_cjk[0]));

/* 线性查找就够了：字表 81 项，且只在换页面时调用 */
const uint8_t *CJK_Find(uint16_t cp)
{
  uint16_t i;

  for (i = 0u; i < g_cjk_count; i++)
  {
    if (g_cjk[i].cp == cp)
    {
      return g_cjk[i].bits;
    }
  }

  return 0;
}
